// ---------------------------------------------------------------- tokenizer
// Token: { type: 'num'|'name'|'op'|'eof', value, pos }
class TokenStream {
  constructor(expression) {
    this.expression = expression;
    this.pos = 0;
    this.current = null;
  }

  tokenize() {
    const out = [];
    for (;;) {
      const t = this.next();
      out.push(t);
      if (t.type === 'eof') return out;
    }
  }

  newToken(type, value, pos) {
    return { type, value, pos: pos != null ? pos : this.pos };
  }

  next() {
    this.isWhitespace();
