    this.current = this.newToken('name', str, startPos);
    this.pos = i;
    return true;
  }

  isRadixInteger() {
    let pos = this.pos;
    const ex = this.expression;
    if (pos >= ex.length - 2 || ex.charAt(pos) !== '0') return false;
